"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["10980"],{30769(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.opcao_declarada_fato.referenciada_por_exigencia_viva","status":422,"titulo":"Uma exig\xeancia documental cita uma op\xe7\xe3o que deixaria de existir"},"descricao":{"codigo":"uniplus.selecao.opcao_declarada_fato.referenciada_por_exigencia_viva","requisitos":[],"oQueAconteceu":["Uma condi\xe7\xe3o do processo ainda cita uma op\xe7\xe3o que a mudan\xe7a pedida faria\\ndesaparecer. Se a mudan\xe7a fosse aceita, o edital seria congelado com uma\\ncondi\xe7\xe3o que cita uma op\xe7\xe3o inexistente, e por isso a API recusa. Nada\\nfoi gravado.","Conta como condi\xe7\xe3o qualquer exig\xeancia que o processo configura sobre o fato:\\nas exig\xeancias de documentos, as regras de preenchimento dos itens, os crit\xe9rios\\nde desempate por fato, as regras de deriva\xe7\xe3o, os termos exigidos, a exibi\xe7\xe3o das se\xe7\xf5es do formul\xe1rio e as condi\xe7\xf5es dos grupos coletados.","O erro chega em dois pedidos:","- **ao redefinir as op\xe7\xf5es de um fato**, quando a nova lista n\xe3o traz uma op\xe7\xe3o\\n  que uma condi\xe7\xe3o cita;\\n- **ao definir a classifica\xe7\xe3o sem base no ENEM**, quando o processo tinha edi\xe7\xf5es\\n  do ENEM declaradas e uma condi\xe7\xe3o cita alguma delas. Sem classifica\xe7\xe3o baseada\\n  em ENEM as edi\xe7\xf5es deixam de existir, e o erro \xe9 apontado no campo\\n  `baseadoEmEnem`.","A mensagem de detalhe indica se a op\xe7\xe3o citada \xe9 de um fato qualquer ou uma\\nedi\xe7\xe3o do ENEM."],"comoResolver":["Antes de remover a op\xe7\xe3o, ajuste ou retire a condi\xe7\xe3o que a cita, e s\xf3 ent\xe3o\\nrepita o pedido. Se a op\xe7\xe3o deve continuar a existir, mantenha-a na lista\\nenviada; na defini\xe7\xe3o da classifica\xe7\xe3o, mantenha-a baseada em ENEM."],"ondeAparece":["Declara\xe7\xe3o das op\xe7\xf5es de um fato do processo seletivo (`PUT /api/selecao/processos-seletivos/{id}/fatos/{fatoCodigo}/opcoes`)","Defini\xe7\xe3o de classifica\xe7\xe3o do processo seletivo (`PUT /api/selecao/processos-seletivos/{id}/classificacao`)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Opcao declarada fato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);